window.__finlexDocLoaded(10219,{"id":10219,"articles":[{"id":1000907,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Establishes the asset-and-liability approach for current and deferred income taxes, uncertain tax positions (2-step MLTN >50%), valuation allowances, and expanded rate reconciliation & cash-taxes-paid disclosures (ASU 2023-09).","seq":0},{"id":1000908,"no":"ASC 740-10","heading":"Enacted Tax Rates, Valuation Allowance, UTPs & ASU 2023-09","text":"• Enacted Rates Only (ASC 740-10-30-8): Deferred taxes MUST use ENACTED tax rates (not 'substantively enacted').\n• Valuation Allowance (ASC 740-10-30-5): Recognize all DTAs in full, then reduce via a contra-asset Valuation Allowance if it is 'more likely than not' (>50%) that some portion will not be realized.\n• Uncertain Tax Positions — UTPs (ASC 740-10-25-6): 2-step model — Step 1: Recognition requires >50% ('more likely than not') technical merits; Step 2: Measurement at the largest amount with >50% cumulative likelihood of realization.\n• ASU 2023-09 (effective FY2025+ for PBEs): Mandates standardized 8-category tabular rate reconciliation (both % and dollar amounts) and disaggregated income taxes paid by federal/state/foreign jurisdiction (>=5% threshold).","seq":1},{"id":1000909,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Key Divergences from IAS 12 / CAS 18: (1) Enacted vs. substantively enacted rates; (2) Intra-entity inventory transfers — ASC 740 defers seller's tax expense as a prepaid until sold to third party (IAS 12 recognizes DTA immediately at buyer's rate); (3) UTPs — ASC 740 uses cumulative-probability largest >50% amount (IFRIC 23 uses most likely amount or expected value); (4) Pillar Two — FASB treats GloBE as an Alternative Minimum Tax (period cost, no deferred tax).","seq":2},{"id":1000910,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
